const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Bradwell Bay Wilderness in Apalachicola National Forest
  const bradwellBay = ee.Geometry.Polygon([
    [[-84.55, 30.15], [-84.55, 30.25], [-84.45, 30.25], [-84.45, 30.15], [-84.55, 30.15]]
  ]);

  // 2. Define time periods
  const earlyApril = ['2004-04-01', '2004-04-10'];
  const lateApril = ['2004-04-21', '2004-04-30'];

  // 3. Function to mask clouds for Landsat 5/7
  function maskClouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(cloudMask);
  }

  // 4. Function to calculate NBR
  function addNBR(image) {
    const nbr = image.normalizedDifference(['SR_B4', 'SR_B7']).rename('NBR');
    return image.addBands(nbr);
  }

  // 5. Acquire Landsat 7 data for early April
  let earlyCol = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(bradwellBay)
    .filterDate(earlyApril[0], earlyApril[1])
    .map(maskClouds)
    .map(addNBR);

  const earlySize = earlyCol.size().getInfo();
  console.log(`Early April images: ${earlySize}`);

  if (earlySize === 0) {
    // Try Landsat 5
    earlyCol = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(bradwellBay)
      .filterDate(earlyApril[0], earlyApril[1])
      .map(maskClouds)
      .map(addNBR);

    const earlySize2 = earlyCol.size().getInfo();
    console.log(`Early April images (Landsat 5): ${earlySize2}`);

    if (earlySize2 === 0) {
      console.log('No data for early April 2004');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 6. Acquire Landsat 7 data for late April
  let lateCol = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(bradwellBay)
    .filterDate(lateApril[0], lateApril[1])
    .map(maskClouds)
    .map(addNBR);

  const lateSize = lateCol.size().getInfo();
  console.log(`Late April images: ${lateSize}`);

  if (lateSize === 0) {
    // Try Landsat 5
    lateCol = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(bradwellBay)
      .filterDate(lateApril[0], lateApril[1])
      .map(maskClouds)
      .map(addNBR);

    const lateSize2 = lateCol.size().getInfo();
    console.log(`Late April images (Landsat 5): ${lateSize2}`);

    if (lateSize2 === 0) {
      console.log('No data for late April 2004');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 7. Create composite images
  const earlyImage = earlyCol.median().select('NBR');
  const lateImage = lateCol.median().select('NBR');

  // 8. Check for valid pixels
  const earlyCount = earlyImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: bradwellBay,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const lateCount = lateImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: bradwellBay,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  console.log(`Early April valid pixels: ${earlyCount}`);
  console.log(`Late April valid pixels: ${lateCount}`);

  if (earlyCount === 0 || lateCount === 0) {
    console.log('No valid pixels after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 9. Define burn threshold (NBR < 0.1 indicates potential burn)
  const burnThreshold = 0.1;
  const earlyBurn = earlyImage.lt(burnThreshold);
  const lateBurn = lateImage.lt(burnThreshold);

  // 10. Calculate burn areas in square meters
  const pixelArea = ee.Image.pixelArea();

  const earlyBurnArea = earlyBurn.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: bradwellBay,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const lateBurnArea = lateBurn.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: bradwellBay,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  console.log(`Early April burn area: ${(earlyBurnArea / 1e6).toFixed(2)} sq km`);
  console.log(`Late April burn area: ${(lateBurnArea / 1e6).toFixed(2)} sq km`);

  // 11. Validation and final answer
  if (earlyBurnArea === null || lateBurnArea === null || isNaN(earlyBurnArea) || isNaN(lateBurnArea)) {
    console.log('Calculation failed - invalid results');
    console.log('<answer>C3</answer>');
    return;
  }

  const increase = lateBurnArea - earlyBurnArea;
  console.log(`Change: ${(increase / 1e6).toFixed(2)} sq km`);

  if (lateBurnArea > earlyBurnArea) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
